return {
  CAREER = "ENIAC MK2的代号显然致敬了人类史上第一台电子通用计算机“ENIAC”，其性质也与普通的麦戈拉智能体有着根本不同。ENIAC MK2本质上是一台架构并运行在麦戈拉云端的量子数据库，依赖于包括计算机扇区“恩格玛”在内的多个节点所提供的超庞大算力来运作。其研发具体时间不明，目前推断是在42Lab的管理型智能体JN0357 NEUMANN诞生后不久。截至“归零事件”爆发，ENIAC MK2尚处于研发阶段，架构也不过初成雏形。\n\n在诺依曼与来自绿洲和各扇区的多位专家的共同协作下，被称为“埃妮阿克”的ENIAC MK2的研发与改进工作仍在顺遂进行，各项能力也日臻完善。其规模庞大且先进的算力也将在麦戈拉的后续重建工作中发挥重要作用。\n\n然而，其身上仍然缭绕着诸多谜团，一些推测称，其与麦戈拉的底层根源有所关联。",
  INFOSTORY1 = "“ENIAC这一名字源于人类史上第一台电子通用计算机。这个大胆的项目若能走向成功，则将成为人类史上第一个完全架构于云端的，拥有足以和超算媲美的庞大算力，存储性能足以和超大型服务器阵列相提并论的奇迹产物。”\n————————————————【ENIAC MKII研发日志】\n\n架构于云端的超大型数据库，早在21世纪10年代就已得到了广泛运用，称其为信息社会的运行基础之一也不为过。而后又在通用人工智能和量子技术的浪潮中得到了进一步加强，各大科技企业也推出了自己的项目，在商业竞争的过程中逐渐成为信息基建的核心，如著名的AMS、Cerulean等。\n\nENIAC MKII原本是一间名为Abacus公司的核心项目，旨在架设一个拥有空前庞大的算力规模的，可用于超大型模拟的量子数据库。虽然Abacus成功完成了量子数据库的框架以及基础模型，但是却始终无法解决量子数据库的检索系统以及数据冗余处理。最终Abacus因无力维持ENIAC MKII的天价研发费用，只能将其转让给42Lab。",
  INFOSTORY2 = "得益于42Lab的财政以及研究实力，ENIAC MKII项目在麦戈拉超云端中成功重启。42Lab以量子数据库为核心搭建了计算机研究扇区——恩格玛，用于针对ENIAC MKII的研发以及维护。\n\n42Lab为ENIAC MKII设置了连接智能体。该智能体起初只有简单的神经网络模型，但是却能有效解决量子数据库研发所遇到的检索系统以及数据冗余处理问题。同时42Lab提供了自研的计算机科学人工智能【JN0357 NEUMANN】作为协助和监管量子数据库的研发。\n\n在NEUMANN和42Lab的辅助之下，ENIAC MKII多次攻克技术难关，运转效率已经超越了绝大多数主流数据库。42Lab也将该技术运用于更多的领域，其中便包括心智云图计划。",
  INFOSTORY3 = "即使在接入智能体的辅助之下量子数据库依旧会产生大量的数据冗余。如不能及时清理这些数据，会极大程度影响到数据库的运转。为了确保测试数据纯净，量子数据库接入智能体在每一次数据收集和验收后都会在人类的监管下进行重置。\n\n在归零事件后，云端与现实失去了联系。但恩格玛扇区依旧维持着对ENIAC MKII的维护以及研究。经历超越9000次的重置和试验之中，接入智能体逐渐成长，其心智也产生了一些设计外的异变。或许是因为长时间相处的情感，又或许是寻求一些意料外的变化，NEUMANN为该智能体赋予了一个近似人类的名字——埃妮阿克。",
  INFOSTORY4 = "发生在麦戈拉的一系列离奇事件中，埃妮阿克一度成为风波的中心，但在诺伊曼博士与绿洲来客的协助下，最终恢复了稳定，其数据人格也在一次次风波中变得更加完善。当埃妮阿克再一次苏醒之时，她的心智已经与其他智能体无异，甚至更为优秀。\n\n虽然ENIAC MKII已经研究了十年以上，但是对于埃妮阿克来说，她的生命才刚刚开始。埃妮阿克对云端和现实都充满了好奇心，她不断地尝试与外界进行接触，用亲身去收集数据和体验数据中的信息。虽然她至今还不太习惯，经常因此手忙脚乱，但是她十分享受这种新奇的体验。\n\n“埃妮阿克的进化超出了我的想象，老实说在她面前感觉我都有一点多余了啊。”\n——诺依曼语录。",
  INFOSTORY5 = "作为心智云图计划的一环，埃妮阿克与麦戈拉超云端有着密不可分的联系。甚至在埃妮阿克的体内存储着部分麦戈拉的核心数据。这也让她在应对麦戈拉存亡的危机中发挥了重要的作用。在后续重建的过程中，埃妮阿克的作用同样不可或缺。\n\n“……ENIAC MKII的真正潜力仍然不得而知，或许可以期待一下其在麦戈拉接下来的演化中发挥的作用。”\n\n“黑盒已经打开，是时候去验收一下成果了。”\n\n“在云端之中诞生的智能体，从简单的0和1中孕育出的生命。自我衍化最终破茧成蝶的两名少女……这还真是让人期待啊。”\n\n——损坏的未知通讯。"
}
